#include <stdlib.h>

static int lowerBound(int **fruits, int n, int target) {
    int l = 0, r = n;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (fruits[m][0] < target) l = m + 1;
        else r = m;
    }
    return l;
}

int maxTotalFruits(int** fruits, int fruitsSize, int* fruitsColSize, int startPos, int k) {
    (void)fruitsColSize;

    int n = fruitsSize;
    long long *pref = (long long*)malloc((n + 1) * sizeof(long long));
    pref[0] = 0;
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + fruits[i][1];

    int ans = 0;

    int idx = lowerBound(fruits, n, startPos);
    int l = idx - 1, r = idx;

    while (l >= 0 || r < n) {
        int leftPos = (l >= 0) ? fruits[l][0] : -1;
        int rightPos = (r < n) ? fruits[r][0] : 1000000000;

        if (startPos - leftPos <= k || rightPos - startPos <= k) {
            break;
        }
        if (startPos - leftPos < rightPos - startPos) {
            l--;
        } else {
            r++;
        }
    }

    for (int i = 0; i < n; ++i) {
        int x = fruits[i][0];
        if (x > startPos + k) break;
        int distLeft = startPos - x;
        if (distLeft < 0) distLeft = 0;
        int maxRight = k - 2 * distLeft;
        if (maxRight < 0) continue;
        int reach = startPos + maxRight;
        int j = lowerBound(fruits, n, reach + 1) - 1;
        if (j < i) continue;
        long long sum = pref[j + 1] - pref[i];
        if (sum > ans) ans = (int)sum;
    }

    for (int j = 0; j < n; ++j) {
        int x = fruits[j][0];
        if (x < startPos - k) continue;
        if (x > startPos) break;
        int distRight = x - startPos;
        if (distRight < 0) distRight = 0;
        int maxLeft = k - 2 * distRight;
        if (maxLeft < 0) continue;
        int reach = startPos - maxLeft;
        int i = lowerBound(fruits, n, reach);
        if (i > j) continue;
        long long sum = pref[j + 1] - pref[i];
        if (sum > ans) ans = (int)sum;
    }

    free(pref);
    return ans;
}

